import { absoluteUrl } from "@/lib/siteUrl"
import { localePath, type Locale } from "@/lib/locale"

/** Dynamic PNG OG routes generated by Next.js opengraph-image.tsx files. */
export const localeOgImage = (locale: Locale): string => {
  void locale
  return absoluteUrl("/es/opengraph-image")
}

export const opportunitiesOgImage = (): string =>
  absoluteUrl(localePath("es", "/opportunities/opengraph-image"))

export const zoneOgImage = (citySlug: string, zoneSlug: string, locale: Locale): string =>
  absoluteUrl(localePath(locale, `/zones/${citySlug}/${zoneSlug}/opengraph-image`))

export const ogImageMeta = (url: string) => ({
  url,
  width: 1200,
  height: 630,
  alt: "LupaCasa",
})
